vector <int> G[N];
int st[N],p[N];

void dfs(int u,int pa,int step){
    p[u]=pa;
    st[u]=step;
    for(int i=0;i<G[u].size();i++){
        int v=G[u][i];
        if(v==pa) continue;
        dfs(v,u,step+1);
    }
}

int LCA(int a,int b){
    while(st[a]>st[b]) a=p[a];
    while(st[a]<st[b]) b=p[b];
    while(a!=b){
        a=p[a];
        b=p[b];
    }
    return a;
}

int n,m,s;
int dis[N],vis[N];
vector <pii> G[N];

void dijkstra(){
    for(int i=1;i<=n;i++) dis[i]=INF;
    priority_queue <pii,vector<pii>,greater<pii>> q;
    dis[s]=0;
    q.push({0,s});
    while(!q.empty()){
        int u=q.top().second;
        q.pop();
        if(vis[u]) continue;
        vis[u]=1;
        for(auto g:G[u]){
            int v=g.first,w=g.second;
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                q.push({dis[v],v});
            }
        }
    }
}

struct Edge{
    int u,v,w;
}e[N];

bool cmp(Edge a,Edge b){
    return a.w<b.w;
}

int kruskal(){
    sort(e+1,e+m+1,cmp);
    for(int i=1;i<=n;i++) pa[i]=i;
    int cnt=0,ans=0;
    for(int i=1;i<=m;i++){
        int ru=find(e[i].u),rv=find(e[i].v);
        if(ru!=rv){
            pa[ru]=rv;
            ans+=e[i].w;
            cnt++;
        }
    }
    if(cnt==n-1) return ans;
    return -1;
}
